float r = glm::length(rij);
if (r == 0.0f) return glm::vec3(0.0f);

float r_h = r / h;
float w_ij = (h - r) * (h - r) * (h - r) / (h * h * h);
if (r_h > 1.0f) return glm::vec3(0.0f);

glm::vec3 rij_norm = glm::normalize(rij);
float lap_w_ij = -4.0f * std::pow(h - r, 2.0f) / (std::::pow(h, 4.0f)) * spikyLap;

float mu_ij = 0.5f * (pi->velocity + pj->velocity);
glm::vec3 v_ij = pj->velocity - pi->velocity;
glm::vec3 force = -mass * viscosity * lap_w_ij * (v_ij - mu_ij * rij_norm);

return force;
